const pick = (lang, en, bn) => lang === "bn" ? bn : en;
const localizedPath = (lang, path) => {
  const clean = path === "/" ? "" : path.startsWith("/") ? path : "/" + path;
  return lang === "bn" ? clean || "/" : "/en" + clean;
};
